def isValid_regular(s):
    pairs = {')': '(', ']': '[', '}': '{'}
    stack = []

    for ch in s:
        if ch in '([{':
            stack.append(ch)
        elif ch in ')]}':
            if not stack:
                return False
            top = stack.pop()
            if pairs[ch] != top:
                return False
        else:
            return False

    return len(stack) == 0

