def nextGreaterElement_regular(nums1, nums2):
    result = []

    for x in nums1:
        found_x = False
        answer = -1

        for y in nums2:
            if y == x:
                found_x = True
            elif found_x and y > x:
                answer = y
                break

        result.append(answer)

    return result

